import type { Meta, StoryObj } from '@storybook/nextjs';
import { expect, within } from 'storybook/test';

import UsageOverview from '@/components/usage/UsageOverview';

const periodStart = new Date(Date.UTC(2026, 5, 1));
const periodEnd = new Date(Date.UTC(2026, 6, 1));

const meta = {
  title: 'Usage/Usage page',
  component: UsageOverview,
  tags: ['autodocs'],
  parameters: {
    layout: 'fullscreen',
    docs: {
      description: {
        component:
          'The /usage page body. Transcript generations are split into captions fetched from YouTube and transcripts generated by Gemini, both for the current month and lifetime.',
      },
    },
  },
  args: {
    usage: {
      used: 42,
      breakdown: { captions: 38, generated: 4 },
      quota: 500,
      periodStart,
      periodEnd,
    },
    lifetime: {
      transcript: { captions: 312, generated: 27 },
      summary: 145,
      article: 63,
    },
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByText('Fetched from YouTube')).toBeVisible();
    await expect(canvas.getByText('Generated by Gemini')).toBeVisible();
    await expect(canvas.getByRole('progressbar')).toHaveAttribute(
      'aria-valuenow',
      String(args.usage.used)
    );
  },
} satisfies Meta<typeof UsageOverview>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {};

